mapper.select:
select roleId
from role
where code = #{code}

select roleId, code, name, description, status, buildIn, createTime, updateTime
from role
where roleId = #{roleId}

select count(1)
from role
where name = #{name}
  and roleId != #{excludeRoleId}

mapper.update:
update role
set name        = #{name},
    description = #{description},
    updateTime  = #{updateTime}
where roleId = #{roleId}

update role
set status     = #{status},
    updateTime = #{updateTime}
where roleId = #{roleId}

mapper.select:
select permissionCode
from role_permission
where roleId = #{roleId}

select count(1)
from user_role
where roleId = #{roleId}
